 "content": "def transform(grid):
    """Project the diagonal-marker color inward from paired border bars."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]

    # Boundary bars are contiguous runs (length >= 2) of one non-background color.
    bars = []
    occupied = set()
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            e = c + 1
            while e < w and g[r][e] == color:
                e += 1
            if color != background and e - c >= 2:
                bars.append((r, c, e, 'h'))
                occupied.update((r, x) for x in range(c, e))
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = g[r][c]
            e = r + 1
            while e < h and g[e][c] == color:
                e += 1
            if color != background and e - r >= 2:
                bars.append((r, c, e, 'v'))
                occupied.update((x, c) for x in range(r, e))
            r = e

    # The remaining non-background object is the diagonal marker; its color
    # determines the projected fill and its size determines the strip width.
    marker_counts = Counter(g[r][c] for r in range(h) for c in range(w)
                            if g[r][c] != background and (r, c) not in occupied)
    if not marker_counts:
        return g
    marker = marker_counts.most_common(1)[0][0]
    thickness = marker_counts[marker]
    for r, start, end, orient in bars:
        length = end - start
        width = min(length, thickness)
        if orient == 'h':
            # The active part of each bar is the segment nearest its right end.
            left = end - width
            direction = 1 if r == 0 else -1
            rr = r + direction
            while 0 <= rr < h:
                for cc in range(left, end):
                    if g[rr][cc] == marker:
                        g[rr][cc] = 4
                    elif g[rr][cc] == background:
                        g[rr][cc] = marker
                rr += direction
        else:
            top = end - width
            direction = 1 if r == 0 else -1
            rr = r + direction
            while 0 <= rr < h:
                for cc in range(top, end):
                    if g[rr][cc] == marker:
                        g[rr][cc] = 4
                    elif g[rr][cc] == background:
                        g[rr][cc] = marker
                rr += direction
    return g

