    bg = counts.most_common(1)[0][0]

    # Find uniform non-background contiguous runs on each board edge.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            e = c + 1
            while e < w and g[r][e] == color:
                e += 1
            if color != bg and e - c >= 2:
                bars.append((color, r, c, e, 'h'))
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = g[r][c]
            e = r + 1
            while e < h and g[e][c] == color:
                e += 1
            if color != bg and e - r >= 2:
                bars.append((color, r, c, e, 'v'))
            r = e

    # Every non-edge singleton is a marker. Markers are converted to 4 when
    # they lie inside a projected region; the fills use the bar's own color.
    edge_cells = set()
    for color, r, a, b, axis in bars:
        if axis == 'h': edge_cells.update((r, c) for c in range(a, b))
        else: edge_cells.update((r0, a) for r0 in range(r, b))
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and (r, c) not in edge_cells]

    for color, r, a, b, axis in bars:
        n = b - a
        if axis == 'h':
            # Bar faces inward; its full span defines the rectangle width.
            rr = r + (1 if r == 0 else -1)
            while 0 <= rr < h:
                for c in range(a, b):
                    if g[rr][c] == bg:
                        g[rr][c] = color
                rr += 1 if r == 0 else -1
        else:
            rr = r + (1 if r == 0 else -1)
            while 0 <= rr < h:
                for c in range(a, b):
                    if g[rr][c] == bg:
                        g[rr][c] = color
                rr += 1 if r == 0 else -1

    # Isolated marker cells get converted into 4 atop the painted bands.
    for r, c, old_color in markers:
        if g[r][c] != bg:
            g[r][c] = 4
    return g

