    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Detect runs on every edge, including runs of background color. Each
    # horizontal bar projects vertically; each vertical bar projects sideways.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            e = c + 1
            while e < w and g[r][e] == color:
                e += 1
            if e - c >= 2:
                bars.append(('h', r, c, e, color))
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = g[r][c]
            e = r + 1
            while e < h and g[e][c] == color:
                e += 1
            if e - r >= 2:
                bars.append(('v', c, r, e, color))
            r = e

    edge = set()
    for axis, fixed, a, b, _ in bars:
        if axis == 'h': edge.update((fixed, x) for x in range(a, b))
        else: edge.update((x, fixed) for x in range(a, b))
    dots = [(r, c, g[r][c]) for r in range(h) for c in range(w)
            if g[r][c] != bg and (r, c) not in edge]
    if not dots:
        return g
    marker = Counter(col for _, _, col in dots).most_common(1)[0][0]
    dotset = {(r, c) for r, c, _ in dots}

    # Only non-background border bars cast their colors into the grid.
    for axis, fixed, a, b, color in bars:
        if color == bg:
            continue
        if axis == 'h':
            dr = 1 if fixed == 0 else -1
            r = fixed + dr
            while 0 <= r < h:
                for c in range(a, b):
                    if g[r][c] == bg:
                        g[r][c] = marker
                r += dr
        else:
            dc = 1 if fixed == 0 else -1
            c = fixed + dc
            while 0 <= c < w:
                for r in range(a, b):
                    if g[r][c] == bg:
                        g[r][c] = marker
                c += dc
    for r, c in dotset:
        if g[r][c] != bg:
            g[r][c] = 4
    return g

