    Bars may be bounded by background-color border runs, which terminate the
    projection. Diagonal marker cells are recolored to 4 when hit.
    """
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    bars = []  # orientation, border coord, span start/end, bar color
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            end = c + 1
            while end < w and g[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                bars.append(('h', r, c, end, color))
            c = end
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = g[r][c]
            end = r + 1
            while end < h and g[end][c] == color:
                end += 1
            if color != bg and end - r >= 2:
                bars.append(('v', c, r, end, color))
            r = end

    edge = set()
    for axis, fixed, a, b, _ in bars:
        if axis == 'h':
            edge.update((fixed, x) for x in range(a, b))
        else:
            edge.update((x, fixed) for x in range(a, b))
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and (r, c) not in edge]
    if not markers:
        return g
    paint = Counter(color for _, _, color in markers).most_common(1)[0][0]
    marker_cells = {(r, c) for r, c, _ in markers}

    # On each edge, background-color runs are opaque stoppers. Rays from
    # source bars fill background in the marker color and stop after a marker.
    for axis, fixed, start, end, _ in bars:
        if axis == 'h':
            step = 1 if fixed == 0 else -1
            for c in range(start, end):
                r = fixed + step
                while 0 <= r < h:
                    if (r, c) in marker_cells:
                        g[r][c] = 4
                        break
                    if g[r][c] not in (bg, paint):
                        break
                    if g[r][c] == bg:
