    """Bars mark rays; matching interior marks are copied into nearby gaps."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Extract monochrome edge runs of length > 1.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            col = g[r][c]
            e = c + 1
            while e < w and g[r][e] == col:
                e += 1
            if e - c > 1:
                bars.append(('h', r, c, e, col))
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            col = g[r][c]
            e = r + 1
            while e < h and g[e][c] == col:
                e += 1
            if e - r > 1:
                bars.append(('v', c, r, e, col))
            r = e

    edge_cells = set()
    for axis, fixed, a, b, _ in bars:
        if axis == 'h': edge_cells.update((fixed, c) for c in range(a, b))
        else: edge_cells.update((r, fixed) for r in range(a, b))
    marks = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] != bg and (r, c) not in edge_cells]
    if not marks:
        return g
    dotcolor = Counter(color for _, _, color in marks).most_common(1)[0][0]
    markcoords = {(r, c) for r, c, _ in marks}

    # Copy the isolated dot color in bars' inward rectangular projection.
    # Marker points become 4; all other cells in projected bands take dotcolor.
    for axis, fixed, a, b, _ in bars:
        dr, dc = (1 if fixed == 0 else -1, 0) if axis == 'h' else (0, 1 if fixed == 0 else -1)
        r, c = fixed + dr, a if axis == 'h' else fixed + dc
        while (0 <= r < h) if axis == 'h' else (0 <= c < w):
            if axis == 'h':
                for cc in range(a, b):
                    if (r, cc) in markcoords: g[r][cc] = 4
                    elif g[r][cc] == bg: g[r][cc] = dotcolor
                r += dr
            else:
                for rr in range(a, b):
                    if (rr, c) in markcoords: g[rr][c] = 4
                    elif g[rr][c] == bg: g[rr][c] = dotcolor
                c += dc
    # Mark any remaining isolated points as 4.
    for r, c in markcoords:
        g[r][c] = 4
    return g

