def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Find monochrome runs of at least two cells along the outer border.
    bars = []  # (orientation, edge index, start, end, color)
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            end = c + 1
            while end < w and g[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                bars.append(('h', r, c, end, color))
            c = end
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = g[r][c]
            end = r + 1
            while end < h and g[end][c] == color:
                end += 1
            if color != bg and end - r >= 2:
                bars.append(('v', c, r, end, color))
            r = end

    edge_cells = set()
    for axis, fixed, start, end, _ in bars:
        if axis == 'h':
            edge_cells.update((fixed, c) for c in range(start, end))
        else:
            edge_cells.update((r, fixed) for r in range(start, end))
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and (r, c) not in edge_cells]
    if not markers:
        return g
    beam_color = Counter(color for _, _, color in markers).most_common(1)[0][0]
    marker_cells = {(r, c) for r, c, _ in markers}

    # Each border-bar cell casts a perpendicular beam inward in marker color.
    # A beam stops at its first marker, which is changed to color 4.
    for axis, fixed, start, end, _ in bars:
        if axis == 'h':
            dr = 1 if fixed == 0 else -1
            for c in range(start, end):
                r = fixed + dr
                while 0 <= r < h:
                    if (r, c) in marker_cells:
                        g[r][c] = 4
                        break
                    if g[r][c] != bg:
                        break
                    g[r][c] = beam_color
                    r += dr
        else:
            dc = 1 if fixed == 0 else -1
            for r in range(start, end):
                c = fixed + dc
                while 0 <= c < w:
                    if (r, c) in marker_cells:
                        g[r][c] = 4
                        break
                    if g[r][c] != bg:
                        break
                    g[r][c] = beam_color
                    c += dc
    return g

